                    .map(|(label, satisfies)| {
                        let satisfied_by: Vec<EventId> = own
                            .iter()
                            .filter(|event| satisfies(&event.kind))
                            .map(|event| event.id.clone())
                            .collect();
                        CriterionRow {
                            label: (*label).to_owned(),
                            status: if satisfied_by.is_empty() {
                                "unsatisfied"
                            } else {
                                "satisfied"
                            }
                            .to_owned(),
                            satisfied_by,
                        }
                    })
                    .collect();
                FeatureCriteria {
                    defined_by: own
                        .iter()
                        .find(|event| event.kind == EventKind::FeatureDefined)
                        .map(|event| event.id.clone()),
                    feature,
                    criteria,
                }
            })
            .collect(),
    }
}
